package notesapi

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"reflect"
	"sync"
	"testing"
)

func do(t *testing.T, s *Server, method, path, body string) *httptest.ResponseRecorder {
	t.Helper()
	var r io.Reader
	if body != "" {
		r = bytes.NewBufferString(body)
	}
	req := httptest.NewRequest(method, path, r)
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)
	return rec
}

func TestCreateListGetDelete(t *testing.T) {
	s := NewServer()

	rec := do(t, s, http.MethodPost, "/notes", `{"title":"t1","body":"b1"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("create: got %d, want 201", rec.Code)
	}
	var created Note
	if err := json.NewDecoder(rec.Body).Decode(&created); err != nil {
		t.Fatalf("decode created: %v", err)
	}
	if created.ID != "1" || created.Title != "t1" || created.Body != "b1" {
		t.Fatalf("created = %+v", created)
	}

	rec = do(t, s, http.MethodPost, "/notes", `{"title":"t2","body":"b2"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("create 2: got %d, want 201", rec.Code)
	}

	rec = do(t, s, http.MethodGet, "/notes", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("list: got %d, want 200", rec.Code)
	}
	var list []Note
	if err := json.NewDecoder(rec.Body).Decode(&list); err != nil {
		t.Fatalf("decode list: %v", err)
	}
	want := []Note{
		{ID: "1", Title: "t1", Body: "b1"},
		{ID: "2", Title: "t2", Body: "b2"},
	}
	if !reflect.DeepEqual(list, want) {
		t.Fatalf("list = %+v, want %+v", list, want)
	}

	rec = do(t, s, http.MethodGet, "/notes/1", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("get: got %d, want 200", rec.Code)
	}
	var got Note
	if err := json.NewDecoder(rec.Body).Decode(&got); err != nil {
		t.Fatalf("decode get: %v", err)
	}
	if !reflect.DeepEqual(got, want[0]) {
		t.Fatalf("get = %+v, want %+v", got, want[0])
	}

	rec = do(t, s, http.MethodDelete, "/notes/1", "")
	if rec.Code != http.StatusNoContent {
		t.Fatalf("delete: got %d, want 204", rec.Code)
	}

	rec = do(t, s, http.MethodGet, "/notes", "")
	if err := json.NewDecoder(rec.Body).Decode(&list); err != nil {
		t.Fatalf("decode list: %v", err)
	}
	if !reflect.DeepEqual(list, []Note{want[1]}) {
		t.Fatalf("list after delete = %+v", list)
	}

	rec = do(t, s, http.MethodGet, "/notes/1", "")
	if rec.Code != http.StatusNotFound {
		t.Fatalf("get deleted: got %d, want 404", rec.Code)
	}
	rec = do(t, s, http.MethodDelete, "/notes/1", "")
	if rec.Code != http.StatusNotFound {
		t.Fatalf("delete missing: got %d, want 404", rec.Code)
	}
	rec = do(t, s, http.MethodGet, "/notes/99", "")
	if rec.Code != http.StatusNotFound {
		t.Fatalf("get missing: got %d, want 404", rec.Code)
	}
}

func TestInvalidJSON(t *testing.T) {
	s := NewServer()
	rec := do(t, s, http.MethodPost, "/notes", `{not json`)
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("invalid json: got %d, want 400", rec.Code)
	}
}

func TestUnknownRoutes(t *testing.T) {
	s := NewServer()
	for _, tc := range []struct{ method, path string }{
		{http.MethodGet, "/"},
		{http.MethodGet, "/other"},
		{http.MethodPost, "/notes/1"},
		{http.MethodPut, "/notes"},
		{http.MethodPut, "/notes/1"},
		{http.MethodDelete, "/notes"},
		{http.MethodGet, "/notes/1/2"},
	} {
		rec := do(t, s, tc.method, tc.path, "")
		if rec.Code != http.StatusNotFound {
			t.Errorf("%s %s: got %d, want 404", tc.method, tc.path, rec.Code)
		}
	}
}

func TestConcurrent(t *testing.T) {
	s := NewServer()
	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			body := fmt.Sprintf(`{"title":"t%d","body":"b%d"}`, i, i)
			rec := do(t, s, http.MethodPost, "/notes", body)
			if rec.Code != http.StatusCreated {
				t.Errorf("create %d: got %d, want 201", i, rec.Code)
			}
			do(t, s, http.MethodGet, "/notes", "")
			do(t, s, http.MethodGet, "/notes/1", "")
			do(t, s, http.MethodDelete, "/notes/1", "")
		}(i)
	}
	wg.Wait()
}

